243	func (s *store) releaseBlocks(obj *object) {
244		seen := make(map[string]bool, len(obj.cids))
245		for _, c := range obj.cids {
246			if seen[c] {
247				continue
248			}
249			seen[c] = true
250			b, ok := s.blocks[c]
251			if !ok {
252				continue
253			}
254			b.refs--
255			if b.refs == 0 {
256				delete(s.blocks, c)
257			}
258		}
259	}
