}

// wellFormedJSON reports whether data is a single well-formed JSON value
// with no duplicate object keys and nothing but whitespace after it.
func wellFormedJSON(data []byte) bool {
	dec := json.NewDecoder(bytes.NewReader(data))
	var walk func() bool
	walk = func() bool {
		tok, err := dec.Token()
		if err != nil {
			return false
		}
		delim, ok := tok.(json.Delim)
		if !ok {
			return true
		}
		switch delim {
		case '{':
			seen := make(map[string]bool)
			for dec.More() {
				key, err := dec.Token()
				if err != nil {
					return false
				}
				name, ok := key.(string)
				if !ok || seen[name] {
					return false
				}
				seen[name] = true
				if !walk() {
					return false
				}
			}
			_, err := dec.Token()
			return err == nil
		case '[':
			for dec.More() {
				if !walk() {
					return false
				}
			}
			_, err := dec.Token()
			return err == nil
		}
		return false
	}
	if !walk() {
		return false
	}
	_, err := dec.Token()
	return err == io.EOF
}

// parseInt converts a JSON number to an int, rejecting fractional values.
func parseInt(n json.Number) (int, error) {
	v, err := strconv.ParseInt(string(n), 10, 0)
	if err != nil {
		return 0, err
	}
	return int(v), nil
}

