	cids := make([]string, 0, len(dataByCID))
	for c := range dataByCID {
		cids = append(cids, c)
	}
	sort.Strings(cids)
	blocks := make([]bundleBlock, 0, len(cids))
	for _, c := range cids {
		blocks = append(blocks, bundleBlock{
			CID:  c,
			Data: base64.StdEncoding.EncodeToString(dataByCID[c]),
		})
	}
